{"code": "all_artist_ids = []
page_index = 0
page_limit = 20

while True:
    artists = apis.spotify.search_artists(genre='edm', min_follower_count=23, page_index=page_index, page_limit=page_limit, access_token=access_token)
    if not artists:
        break
    all_artist_ids.extend([a['artist_id'] for a in artists])
    page_index += 1

for artist_id in all_artist_ids:
    apis.spotify.follow_artist(artist_id=artist_id, access_token=access_token)

all_artist_ids"}

