{"code": "# Get all user's albums
my_albums = get_all_pages(apis.spotify.show_album_library, access_token=access_token)
print(f"Total albums: {len(my_albums)}")

# Get all liked albums
liked_albums = get_all_pages(apis.spotify.show_liked_albums, access_token=access_token)
liked_album_ids = {a['album_id'] for a in liked_albums}
print(f"Liked albums: {len(liked_album_ids)}")

# Albums to keep: liked OR all songs downloaded
albums_to_remove = []
for album in my_albums:
    album_id = album['album_id']
    if album_id in liked_album_ids:
        continue  # Keep liked albums
    # Check if all songs in album are downloaded
    album_songs = apis.spotify.show_album(album_id=album_id, access_token=access_token)['songs']
    album_song_ids = {s['song_id'] for s in album_songs}
    if album_song_ids.issubset(downloaded_song_ids):
        continue  # Keep if all songs downloaded
    albums_to_remove.append(album)

print(f"Albums to remove: {len(albums_to_remove)}")"}

